package com.example.inventory.service; import com.example.inventory.model.StockItem; import com.example.inventory.repo.StockRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class InventoryService { private final StockRepository r; public InventoryService(StockRepository r){this.r=r;} @Transactional public StockItem reserve(String sku,int qty){if(qty<=0) throw new IllegalArgumentException("quantity must be positive"); StockItem s=r.findBySku(sku).orElseThrow(()->new IllegalArgumentException("SKU not found")); if(s.quantity<qty) throw new IllegalStateException("insufficient stock"); s.quantity-=qty; return r.save(s);} public StockItem get(String sku){return r.findBySku(sku).orElseThrow();} }
